#version 330
in vec2 uv;in vec3 normal;in vec3 world;in vec4 color;
uniform sampler2D texture0;uniform vec4 colDiffuse;uniform int woodMode;uniform vec3 eye;uniform vec3 pinShadows[10];uniform vec3 ballShadow;out vec4 finalColor;
float hash(float n){return fract(sin(n)*43758.5453);}
void main(){vec3 n=normalize(normal),v=normalize(eye-world);vec3 tex=texture(texture0,uv).rgb*colDiffuse.rgb*color.rgb;vec3 key=normalize(vec3(-.35,.85,-.4));float diffuse=max(dot(n,key),0.0);float rim=pow(1.0-max(dot(n,v),0.0),3.0);vec3 lit=tex*(vec3(.24,.30,.37)+diffuse*vec3(.94,.83,.65));lit+=tex*max(dot(n,normalize(vec3(.7,.2,.6))),0.0)*vec3(.12,.22,.30);float gloss=pow(max(dot(n,normalize(key+v)),0.0),woodMode==1?85.0:48.0);lit+=vec3(.85,.91,1.0)*gloss*(woodMode==1?.45:.38)+rim*vec3(.035,.07,.09);
if(woodMode==1){float plank=floor((world.x+30.0)*3.4);float grain=sin(world.x*180.0+sin(world.z*.8+plank)*2.0+sin(world.z*3.0)*.3);float aa=1.0-smoothstep(.5,2.5,fwidth(world.x*180.0));lit*=.88+.1*hash(plank)+grain*.025*aa;float seam=fract((world.x+30.0)*3.4);lit*=mix(.65,1.0,smoothstep(0.0,.025,seam)*smoothstep(0.0,.025,1.0-seam));float end=fract((world.z+hash(plank)*7.0)/4.5);lit*=mix(.78,1.0,smoothstep(0.0,.006,end));float shadow=0.0;for(int i=0;i<10;++i){vec2 d=(world.xz-pinShadows[i].xz)/vec2(.50,.75);shadow+=exp(-dot(d,d)*2.0)*.46;}vec2 d=(world.xz-ballShadow.xz)/vec2(.7,1.0);shadow+=exp(-dot(d,d)*2.0)*.55;lit*=1.0-min(shadow,.70);for(int side=-1;side<=1;side+=2){float strip=exp(-pow((world.x-float(side)*3.4)/.35,2.0));float bands=.5+.5*cos(world.z*.8);lit+=vec3(.30,.37,.39)*strip*bands*.24;}}
if(woodMode==2){vec2 brick=vec2(world.z*2.1+floor(world.y*4.5)*.5,world.y*4.5);vec2 f=fract(brick);float mortar=step(.06,f.x)*step(.09,f.y);lit*=.7+.3*hash(floor(brick.x)+floor(brick.y)*19);lit=mix(vec3(.15,.17,.18),lit,mortar);}float fog=1.0-exp(-length(eye-world)*.004);lit=mix(lit,vec3(.08,.13,.20),fog);finalColor=vec4(lit,colDiffuse.a*color.a);}
